const icons = {
  primary: "play",
  secondary: "settings",
  ghost: "more",
  danger: "trash",
};

export default function IconButtonExample() {
  return (
    <Playground
      knobs={{
        variant: { options: buttonVariants, value: "primary" },
        size: { options: sizes, value: "md" },
        round: { value: false },
        disabled: { value: false },
      }}
      code={(v, c) =>
        jsx("IconButton", {
          icon: icons[v.variant as keyof typeof icons],
          label: "Воспроизвести",
          variant: v.variant === "secondary" ? undefined : v.variant,
          size: c.size,
          round: v.round,
          disabled: v.disabled,
        })
      }
      extra={
        <Compare
          items={buttonVariants.map((variant) => ({
            label: variant,
            node: (
              <U.IconButton
                variant={variant}
                size="sm"
                icon={icons[variant]}
                label={variant}
              />
            ),
          }))}
        />
      }
    >
      {(v) => (
        <U.IconButton
          icon={icons[v.variant as keyof typeof icons]}
          label="Воспроизвести"
          variant={v.variant}
          size={v.size}
          round={v.round}
          disabled={v.disabled}
        />
      )}
    </Playground>
  );
}
